package com.tradingsimulator.tradingengine.botstrategies; import com.tradingsimulator.model.*; import java.math.BigDecimal; import java.util.List; public final class RsiThresholdStrategy extends BaseStrategy { private final double low,high; public RsiThresholdStrategy(double l,double h){super(1);if(l>=h)throw new IllegalArgumentException("RSI thresholds invalid");low=l;high=h;} public OrderSide signal(List<BigDecimal> p){return null;} public OrderSide signal(double rsi){return rsi<low?OrderSide.BUY:rsi>high?OrderSide.SELL:null;} }
